#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    long long kl;
    cin >> n >> kl;

    const int fmod = 998244353;

    if (kl >= n) {
        cout << 0 << "\n";
        return 0;
    }

    int k = (int)kl;

    vector<long long> fact(n + 1, 1);
    vector<long long> ifact(n + 1, 0);

    for (int i = 1; i <= n; i++) {
        fact[i] = (fact[i - 1] * i) % fmod;
    }

    function<long long(int)> fpow = [&](int a, int b) {
        long long res = 1;
        long long base = a;
        int exp = b;
        while (exp > 0) {
            if (exp & 1) res = (res * base) % fmod;
            base = (base * base) % fmod;
            exp >>= 1;
        }
        return res;
    };

    function<long long(int)> ifact_fn = [&](int x) {
        if (ifact[x] > 0) {
            return ifact[x];
        } else {
            return ifact[x] = fpow(fact[x], fmod - 2);
        }
    };

    long long answer = 0;
    int sign = 1;

    for (int i = 0; i <= n - k; i++) {
        long long term = sign * fpow(n - k - i, n) % fmod;
        term = (term * fact[n - k]) % fmod;
        term = (term * ifact_fn(i)) % fmod;
        term = (term * ifact_fn(n - k - i)) % fmod;
        if (term < 0) term += fmod;
        answer = (answer + term) % fmod;
        sign = -sign;
    }

    long long result = (answer * fact[n]) % fmod;
    result = (result * ifact_fn(k)) % fmod;
    result = (result * ifact_fn(n - k)) % fmod;

    if (k == 0) {
        cout << result << "\n";
    } else {
        cout << (result * 2) % fmod << "\n";
    }

    return 0;
}

